import React, { useEffect, useState } from 'react';
import { 
  Button, 
  Dropdown,
  Form, 
  Header, 
  Label, 
  Pagination, 
  Segment, 
  Select, 
  Table, 
  Popup, 
} from 'semantic-ui-react';
import {
  API,
  copy,
  isAdmin,
  showError,
  showSuccess,
  showWarning,
  timestamp2string,
} from '../helpers';
import { useTranslation } from 'react-i18next';

import { ITEMS_PER_PAGE_OPTIONS } from '../constants';
import { renderColorLabel } from '../helpers/render';
import { Link } from 'react-router-dom';

function renderTimestamp(timestamp, request_id) {
  const s = timestamp2string(timestamp);
  // dyt-42: 两行显示 (日期 / 时间)，列宽收窄
  const parts = s.split(' ');
  const date = parts[0] || '';
  const time = parts[1] || '';
  return (
    <code
      onClick={async () => {
        if (await copy(request_id)) {
          showSuccess(`已复制请求 ID：${request_id}`);
        } else {
          showWarning(`请求 ID 复制失败：${request_id}`);
        }
      }}
      // dyt-45: 加 nowrap 让日期 "2026-06-13" 不换行
      style={{ cursor: 'pointer', fontSize: '11px', lineHeight: '1.2', whiteSpace: 'nowrap' }}
    >
      <div>{date}</div>
      <div>{time}</div>
    </code>
  );
}

function renderType(log) {
  const type = log.type;
  const content = log.content || '';
  if (type === 5) {
    return (
      <Label basic color='violet'>
        测试
      </Label>
    );
  }
  if (type === 4 || content.includes('探测失败') || content.includes('探针失败') || content.includes('渠道尝试')) {
    return (
      <Label basic color='red'>
        失败
      </Label>
    );
  }
  if (content.includes('探测成功') || content.includes('探针确认')) {
    return (
      <Label basic color='green'>
        成功
      </Label>
    );
  }
  if (type === 2 && log.completion_tokens === 0) {
    // 新格式：探测成功（completion_tokens=0）
    return (
      <Label basic color='green'>
        成功
      </Label>
    );
  }
  if (content.startsWith('回复完成')) {
    return (
      <Label basic color='orange'>
        完成
      </Label>
    );
  }
  if (type === 2) {
    // 消费日志
    return (
      <Label basic color='olive'>
        消费
      </Label>
    );
  }
  return (
    <Label basic color='black'>
      未知
    </Label>
  );
}

function getColorByElapsedTime(elapsedTime) {
  if (elapsedTime === undefined || elapsedTime === 0) {
    return { backgroundColor: '#767676', borderColor: '#767676', color: '#fff' };
  }
  // 0→10000ms 映射 hue 120(绿)→0(红)，连续渐变
  const t = Math.max(0, Math.min(1, elapsedTime / 10000));
  const hue = Math.round((1 - t) * 120);
  return {
    backgroundColor: `hsl(${hue}, 70%, 42%)`,
    borderColor: `hsl(${hue}, 70%, 42%)`,
    color: '#fff',
  };
}

function processContent(content, type, log) {
  if (!content) return '';
  // 旧版倍率日志：不显示
  if (content.startsWith('倍率：')) return '';
  // 后端已写入前缀，直接返回
  return content;
}

function renderDetail(log) {
  const raw = log.content || '';
  const processed = processContent(raw, log.type, log);
  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '2px' }}>
      {processed ? (
        <span
          style={{
            wordBreak: 'break-word',
            color: '#555',
            lineHeight: '1.4',
            // dyt-45: 详情 2→3 行
            display: '-webkit-box',
            WebkitLineClamp: 3,
            WebkitBoxOrient: 'vertical',
            overflow: 'hidden',
          }}
          title={processed}
        >
          {processed}
        </span>
      ) : <span style={{ color: 'lightgray' }}>—</span>}
      <div style={{ display: 'flex', gap: '4px', flexWrap: 'wrap' }}>
        {log.elapsed_time ? (
          <Label
            size={'mini'}
            style={getColorByElapsedTime(log.elapsed_time)}
          >
            {log.elapsed_time} ms
          </Label>
        ) : null}
        {log.is_stream ? (
          <Label size={'mini'} color='pink'>
            Stream
          </Label>
        ) : null}
        {log.system_prompt_reset ? (
          <Label basic size={'mini'} color='red'>
            SPR
          </Label>
        ) : null}
      </div>
    </div>
  );
}

const LogsTable = () => {
  const { t } = useTranslation();
  const [logs, setLogs] = useState([]);
  const [showStat, setShowStat] = useState(false);
  const [loading, setLoading] = useState(true);
  const [activePage, setActivePage] = useState(1);
  const [hasMore, setHasMore] = useState(true);
  const [itemsPerPage, setItemsPerPage] = useState(() => parseInt(localStorage.getItem('itemsPerPage') || '10') || 10);
  const [orderBy, setOrderBy] = useState('');
  const [searchKeyword, setSearchKeyword] = useState('');
  const [searching, setSearching] = useState(false);
  const [logType, setLogType] = useState(0);
  const isAdminUser = isAdmin();
  let now = new Date();
  const [inputs, setInputs] = useState({
    username: '',
    token_name: '',
    model_name: '',
    start_timestamp: timestamp2string(0),
    end_timestamp: timestamp2string(now.getTime() / 1000 + 3600),
    channel: '',
  });
  const {
    username,
    token_name,
    model_name,
    start_timestamp,
    end_timestamp,
    channel,
  } = inputs;

  const [stat, setStat] = useState({
    quota: 0,
    token: 0,
  });

  const LOG_OPTIONS = [
    { key: '0', text: '全部', value: 0 },
    { key: '2', text: '消费', value: 2 },
    { key: '5', text: '测试', value: 5 },
  ];

  const handleInputChange = (e, { name, value }) => {
    setInputs((inputs) => ({ ...inputs, [name]: value }));
  };

  const getLogSelfStat = async () => {
    let localStartTimestamp = Date.parse(start_timestamp) / 1000;
    let localEndTimestamp = Date.parse(end_timestamp) / 1000;
    let res = await API.get(
      `/api/log/self/stat?type=${logType}&token_name=${token_name}&model_name=${model_name}&start_timestamp=${localStartTimestamp}&end_timestamp=${localEndTimestamp}`
    );
    const { success, message, data } = res.data;
    if (success) {
      setStat(data);
    } else {
      showError(message);
    }
  };

  const getLogStat = async () => {
    let localStartTimestamp = Date.parse(start_timestamp) / 1000;
    let localEndTimestamp = Date.parse(end_timestamp) / 1000;
    let res = await API.get(
      `/api/log/stat?type=${logType}&username=${username}&token_name=${token_name}&model_name=${model_name}&start_timestamp=${localStartTimestamp}&end_timestamp=${localEndTimestamp}&channel=${channel}`
    );
    const { success, message, data } = res.data;
    if (success) {
      setStat(data);
    } else {
      showError(message);
    }
  };

  const handleEyeClick = async () => {
    if (!showStat) {
      if (isAdminUser) {
        await getLogStat();
      } else {
        await getLogSelfStat();
      }
    }
    setShowStat(!showStat);
  };

  // showUserTokenQuota always returns true: token 列始终显示
  const showUserTokenQuota = () => true;

  function renderTokPerSec(log) {
    // 探针日志（completion_tokens=0）的 elapsed_time = TTFT，tok/s 无意义
    if (!log.elapsed_time || log.elapsed_time === 0) return '';
    const completionTokens = log.completion_tokens || 0;
    if (completionTokens === 0) return ''; // 探针确认日志跳过
    // tok/s = 输出 tokens / 生成时间（秒），不含输入 tokens
    const speed = completionTokens / (log.elapsed_time / 1000);
    return speed.toFixed(1);
  }

  const loadLogs = async (startIdx, size) => {
    let url = '';
    let localStartTimestamp = Date.parse(start_timestamp) / 1000;
    let localEndTimestamp = Date.parse(end_timestamp) / 1000;
    const sizeParam = size !== undefined ? size : itemsPerPage;
    if (isAdminUser) {
      url = `/api/log/?p=${startIdx}&size=${sizeParam}&type=${logType}&username=${username}&token_name=${token_name}&model_name=${model_name}&start_timestamp=${localStartTimestamp}&end_timestamp=${localEndTimestamp}&channel=${channel}`;
    } else {
      url = `/api/log/self/?p=${startIdx}&size=${sizeParam}&type=${logType}&token_name=${token_name}&model_name=${model_name}&start_timestamp=${localStartTimestamp}&end_timestamp=${localEndTimestamp}`;
    }
    const res = await API.get(url);
    const { success, message, data } = res.data;
    if (success) {
      // 返回满一页说明可能还有更多（服务端无总数，靠此推断，保证"下一页"可点）
      setHasMore(data.length >= sizeParam);
      if (startIdx === 0) {
        setLogs(data);
      } else {
        let newLogs = [...logs];
        newLogs.splice(startIdx * itemsPerPage, data.length, ...data);
        setLogs(newLogs);
      }
    } else {
      showError(message);
    }
    setLoading(false);
  };

  const onPaginationChange = (e, { activePage }) => {
    (async () => {
      if (activePage === Math.ceil(logs.length / itemsPerPage) + 1) {
        // In this case we have to load more data and then append them.
        await loadLogs(activePage - 1);
      }
      setActivePage(activePage);
    })();
  };

  const refresh = async () => {
    setLoading(true);
    setActivePage(1);
    await loadLogs(0);
  };

  useEffect(() => {
    refresh().then();
  }, [logType]);

  const searchLogs = async () => {
    if (searchKeyword === '') {
      // if keyword is blank, load files instead.
      await loadLogs(0);
      setActivePage(1);
      return;
    }
    setSearching(true);
    const res = await API.get(`/api/log/self/search?keyword=${searchKeyword}`);
    const { success, message, data } = res.data;
    if (success) {
      setLogs(data);
      setHasMore(false);
      setActivePage(1);
    } else {
      showError(message);
    }
    setSearching(false);
  };

  const handleItemsPerPageChange = (e, { value }) => {
    setItemsPerPage(value);
    localStorage.setItem('itemsPerPage', value.toString());
    setActivePage(1);
    loadLogs(0, value);
  };

  const handleKeywordChange = async (e, { value }) => {
    setSearchKeyword(value.trim());
  };

  const sortLog = (key) => {
    if (logs.length === 0) return;
    setLoading(true);
    let sortedLogs = [...logs];
    if (typeof sortedLogs[0][key] === 'string') {
      sortedLogs.sort((a, b) => {
        return ('' + a[key]).localeCompare(b[key]);
      });
    } else {
      sortedLogs.sort((a, b) => {
        if (a[key] === b[key]) return 0;
        if (a[key] > b[key]) return -1;
        if (a[key] < b[key]) return 1;
      });
    }
    if (sortedLogs[0].id === logs[0].id) {
      sortedLogs.reverse();
    }
    setLogs(sortedLogs);
    setLoading(false);
  };

  return (
    <>
      <Header as='h3'>
        {t('log.usage_details')}
        {!showStat && (
          <span
            onClick={handleEyeClick}
            style={{ cursor: 'pointer', color: 'gray', marginLeft: 8 }}
          >
            {t('log.click_to_view')}
          </span>
        )}
      </Header>
      <Form>
        <Form.Group className='logs-filter-group'>
          <Form.Input
            fluid
            label={t('log.table.token_name')}
            size={'small'}
            width={3}
            value={token_name}
            placeholder={t('log.table.token_name_placeholder')}
            name='token_name'
            onChange={handleInputChange}
          />
          <Form.Input
            fluid
            label={t('log.table.model_name')}
            size={'small'}
            width={3}
            value={model_name}
            placeholder={t('log.table.model_name_placeholder')}
            name='model_name'
            onChange={handleInputChange}
          />
          <Form.Input
            fluid
            label={t('log.table.start_time')}
            size={'small'}
            width={4}
            value={start_timestamp}
            type='datetime-local'
            name='start_timestamp'
            onChange={handleInputChange}
          />
          <Form.Input
            fluid
            label={t('log.table.end_time')}
            size={'small'}
            width={4}
            value={end_timestamp}
            type='datetime-local'
            name='end_timestamp'
            onChange={handleInputChange}
          />
          <Form.Button
            fluid
            label={t('log.buttons.query')}
            size={'small'}
            width={2}
            onClick={refresh}
          >
            {t('log.buttons.submit')}
          </Form.Button>
        </Form.Group>
        {isAdminUser && (
          <>
            <Form.Group className='logs-filter-group logs-filter-group-secondary'>
              <Form.Input
                fluid
                label={t('log.table.channel_id')}
                size={'small'}
                width={3}
                value={channel}
                placeholder={t('log.table.channel_id_placeholder')}
                name='channel'
                onChange={handleInputChange}
              />
              <Form.Input
                fluid
                label={t('log.table.username')}
                size={'small'}
                width={3}
                value={username}
                placeholder={t('log.table.username_placeholder')}
                name='username'
                onChange={handleInputChange}
              />
            </Form.Group>
          </>
        )}
        <Form.Input
          icon='search'
          placeholder={t('log.search')}
          value={searchKeyword}
          onChange={(e, { value }) => setSearchKeyword(value)}
        />
      </Form>
      <Table
        basic={'very'}
        compact
        size='small'
        className={`logs-table ${isAdminUser ? 'admin-logs' : 'self-logs'}`}
      >
        <Table.Header>
          <Table.Row>
            <Table.HeaderCell
              style={{ cursor: 'pointer', whiteSpace: 'nowrap', textAlign: 'right' }}
              onClick={() => {
                sortLog('created_time');
              }}
              width={1}
            >
              {t('log.table.time')}
            </Table.HeaderCell>
            {isAdminUser && (
              <Table.HeaderCell
                style={{ cursor: 'pointer', whiteSpace: 'nowrap' }}
                onClick={() => {
                  sortLog('channel');
                }}
                width={1}
              >
                {t('log.table.channel')}
              </Table.HeaderCell>
            )}
            <Table.HeaderCell
              style={{ cursor: 'pointer', whiteSpace: 'nowrap' }}
              onClick={() => {
                sortLog('type');
              }}
              width={1}
            >
              {t('log.table.type')}
            </Table.HeaderCell>
            <Table.HeaderCell
              style={{ cursor: 'pointer', whiteSpace: 'nowrap' }}
              onClick={() => {
                sortLog('model_name');
              }}
              width={2}
            >
              {t('log.table.model')}
            </Table.HeaderCell>
            {showUserTokenQuota() && (
              <>
                {isAdminUser && (
                  <Table.HeaderCell
                    style={{ cursor: 'pointer', whiteSpace: 'nowrap' }}
                    onClick={() => {
                      sortLog('username');
                    }}
                    width={1}
                  >
                    {t('log.table.username')}
                  </Table.HeaderCell>
                )}
                <Table.HeaderCell
                  style={{ cursor: 'pointer', whiteSpace: 'nowrap' }}
                  onClick={() => {
                    sortLog('token_name');
                  }}
                  width={1}
                >
                  {t('log.table.token_name')}
                </Table.HeaderCell>
                <Table.HeaderCell
                  style={{ cursor: 'pointer', whiteSpace: 'nowrap', textAlign: 'right' }}
                  onClick={() => {
                    sortLog('prompt_tokens');
                  }}
                  width={1}
                >
                  {t('log.table.prompt_tokens')}
                </Table.HeaderCell>
                <Table.HeaderCell
                  style={{ cursor: 'pointer', whiteSpace: 'nowrap', textAlign: 'right' }}
                  onClick={() => {
                    sortLog('cache_read_tokens');
                  }}
                  width={1}
                >
                  {t('log.table.cache_read')}
                </Table.HeaderCell>
                <Table.HeaderCell
                  style={{ cursor: 'pointer', whiteSpace: 'nowrap', textAlign: 'right' }}
                  onClick={() => {
                    sortLog('cache_creation_tokens');
                  }}
                  width={1}
                >
                  {t('log.table.cache_write')}
                </Table.HeaderCell>
                <Table.HeaderCell
                  style={{ cursor: 'pointer', whiteSpace: 'nowrap', textAlign: 'right' }}
                  onClick={() => {
                    sortLog('completion_tokens');
                  }}
                  width={1}
                >
                  {t('log.table.completion_tokens')}
                </Table.HeaderCell>
                <Table.HeaderCell
                  style={{ cursor: 'pointer', whiteSpace: 'nowrap', textAlign: 'right' }}
                  width={1}
                >
                  tok/s
                </Table.HeaderCell>
              </>
            )}
            <Table.HeaderCell style={{ whiteSpace: 'nowrap' }}>
              {t('log.table.detail')}
            </Table.HeaderCell>
          </Table.Row>
        </Table.Header>

        <Table.Body>
          {logs
            .slice(
              (activePage - 1) * itemsPerPage,
              activePage * itemsPerPage
            )
            .map((log, idx) => {
              if (log.deleted) return <></>;
              return (
                <Table.Row key={log.id}>
                  <Table.Cell>
                    {renderTimestamp(log.created_at, log.request_id)}
                  </Table.Cell>
                  {isAdminUser && (
                    <Table.Cell>
                      {log.channel ? (
                        <Label
                          basic
                          as={Link}
                          to={`/channel/edit/${log.channel}`}
                        >
                          {log.channel}
                        </Label>
                      ) : (
                        ''
                      )}
                    </Table.Cell>
                  )}
                  <Table.Cell>{renderType(log)}</Table.Cell>
                  <Table.Cell>
                    {log.model_name ? renderColorLabel(log.model_name) : ''}
                  </Table.Cell>
                  {showUserTokenQuota() && (
                    <>
                      {isAdminUser && (
                        <Table.Cell style={{ paddingRight: '10px' }}>
                          {log.username ? (
                            <Label
                              basic
                              as={Link}
                              to={`/user/edit/${log.user_id}`}
                            >
                              {log.username}
                            </Label>
                          ) : (
                            ''
                          )}
                        </Table.Cell>
                      )}
                      <Table.Cell>
                        {log.token_name ? renderColorLabel(log.token_name) : ''}
                      </Table.Cell>

                      <Table.Cell style={{ whiteSpace: 'nowrap', textAlign: 'right' }}>
                        {log.prompt_tokens ? log.prompt_tokens : '—'}
                      </Table.Cell>
                      <Table.Cell style={{ whiteSpace: 'nowrap', textAlign: 'right' }}>
                        {log.cache_read_tokens ? log.cache_read_tokens : '—'}
                      </Table.Cell>
                      <Table.Cell style={{ whiteSpace: 'nowrap', textAlign: 'right' }}>
                        {log.cache_creation_tokens ? log.cache_creation_tokens : '—'}
                      </Table.Cell>
                      <Table.Cell style={{ whiteSpace: 'nowrap', textAlign: 'right' }}>
                        {log.completion_tokens ? log.completion_tokens : '—'}
                      </Table.Cell>
                      <Table.Cell style={{ whiteSpace: 'nowrap', textAlign: 'right' }}>
                        {renderTokPerSec(log)}
                      </Table.Cell>
                    </>
                  )}

                  <Table.Cell>{renderDetail(log)}</Table.Cell>
                </Table.Row>
              );
            })}
        </Table.Body>

        <Table.Footer>
          <Table.Row>
            <Table.HeaderCell colSpan={isAdminUser ? '12' : '11'}>
              <Select
                placeholder={t('log.type.select')}
                options={LOG_OPTIONS}
                style={{ marginRight: '8px' }}
                name='logType'
                value={logType}
                onChange={(e, { name, value }) => {
                  setLogType(value);
                }}
              />
              <Button size='small' onClick={refresh} loading={loading}>
                {t('log.buttons.refresh')}
              </Button>
              <Dropdown
                selection
                options={ITEMS_PER_PAGE_OPTIONS}
                value={itemsPerPage}
                onChange={handleItemsPerPageChange}
                placeholder='10'
                style={{ marginRight: '10px' }}
              />
              <Pagination
                floated='right'
                activePage={activePage}
                onPageChange={onPaginationChange}
                size='small'
                siblingRange={1}
                totalPages={
                  logs.length === 0
                    ? 1
                    : Math.ceil(logs.length / itemsPerPage) + (hasMore ? 1 : 0)
                }
              />
            </Table.HeaderCell>
          </Table.Row>
        </Table.Footer>
      </Table>
    </>
  );
};

export default LogsTable;
